from fastapi import FastAPI, Depends, Response
from typing import Annotated
import pytest
from fastapi.testclient import TestClient

app = FastAPI()

def modify_response(response: Response):
    response.headers["X-Custom-Header"] = "custom-value"
    return response

@app.get("/test1")
def endpoint1(response: Annotated[Response, Depends(modify_response)]):
    return {"message": "test1"}

@app.get("/test2")
def endpoint2(response: Response = Depends(modify_response)):
    return {"message": "test2"}

@app.get("/test3")
def endpoint3(response: Response):
    return {"message": "test3"}

client = TestClient(app)

def test_endpoint1():
    response = client.get("/test1")
    assert response.status_code == 200
    assert response.headers["X-Custom-Header"] == "custom-value"
    assert response.json() == {"message": "test1"}

def test_endpoint2():
    response = client.get("/test2")
    assert response.status_code == 200
    assert response.headers["X-Custom-Header"] == "custom-value"
    assert response.json() == {"message": "test2"}

def test_endpoint3():
    response = client.get("/test3")
    assert response.status_code == 200
    assert "X-Custom-Header" not in response.headers
    assert response.json() == {"message": "test3"}

if __name__ == "__main__":
    try:
        test_endpoint1()
        print("test_endpoint1 passed")
        test_endpoint2()
        print("test_endpoint2 passed")
        test_endpoint3()
        print("test_endpoint3 passed")
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

